const item = $input.first();
const body = item.json.body ?? item.json;
const p    = body.payload ?? body;

// Текст заявки пишет посетитель сайта: экранируем символы Markdown, иначе Telegram отклонит сообщение
const esc = (value) => String(value ?? '').replace(/([_*`\[])/g, '\\$1');

const intentLabel   = { high: '🔥 Горячий', medium: '🌡 Тёплый', low: '❄️ Холодный' };
const sourceLabel   = { chat: '💬 Чат', manual: '👆 Кнопка', calculator: '🧮 Калькулятор' };
const categoryLabel = { buy: '🏠 Покупка', rent_out: '🔑 Хочет сдать', consult: '❓ Консультация', spam: '🗑 Спам' };
const urgencyLabel  = { high: '⚡ срочно', medium: '⏳ есть срок', low: 'без спешки' };

const budgetStr = (p.budgetMin || p.budgetMax)
  ? `${p.budgetMin ? (p.budgetMin / 1_000_000).toFixed(1) + ' млн' : '?'} — ${p.budgetMax ? (p.budgetMax / 1_000_000).toFixed(1) + ' млн' : '?'} ₽`
  : 'не указан';

const message = p.message ? esc(p.message.length > 500 ? p.message.slice(0, 500) + '…' : p.message) : '';

const text = [
  `🆕 *Новый лид #${p.leadId}*`,
  ``,
  `👤 ${esc(p.userName) || 'Аноним'} ${p.userPhone ? `· ${esc(p.userPhone)}` : ''}`,
  `📧 ${esc(p.userEmail) || '—'}`,
  ``,
  p.category ? `${categoryLabel[p.category] || p.category}${p.urgency ? ` · ${urgencyLabel[p.urgency] || p.urgency}` : ''}` : '',
  p.summary ? `🤖 ${esc(p.summary)}` : '',
  message ? `💬 «${message}»` : '',
  p.category || message ? `` : '',
  `📊 Скор: *${p.score}/20*`,
  `${intentLabel[p.intent] || '❓ Неизвестно'}`,
  `💰 Бюджет: ${budgetStr}`,
  `📍 Источник: ${sourceLabel[p.source] || p.source}`,
  ``,
  p.snapshot?.viewedPropertiesCount
    ? `👁 Просмотрел ЖК: ${p.snapshot.viewedPropertiesCount}`
    : '',
].filter((line, i, all) => line !== '' || (all[i - 1] !== '' && i > 0)).join('\n').trim();

const isHot = p.isHot ?? (p.category !== 'spam' && (p.score ?? 0) >= 10);

return [{ json: { text, leadId: p.leadId, score: p.score ?? 0, isHot, isSpam: p.category === 'spam', urgency: p.urgency ?? null } }];
